"use client";

import { driver, type Config, type Driver } from "driver.js";

export function createDriverTour(config?: Config): Driver {
  return driver({
    animate: true,
    allowClose: true,
    allowKeyboardControl: true,
    overlayOpacity: 0.12,
    smoothScroll: true,
    stagePadding: 10,
    stageRadius: 18,
    showProgress: true,
    nextBtnText: "Lanjut",
    prevBtnText: "Sebelumnya",
    doneBtnText: "Selesai",
    popoverClass: "app-driver-popover",
    onPopoverRender: (popover, opts) => {
      popover.closeButton.textContent = "Lewati";
      popover.closeButton.setAttribute("aria-label", "Lewati tour");
      popover.closeButton.classList.add("app-driver-skip-btn");
      opts.config.onPopoverRender?.(popover, opts);
    },
    ...config,
  });
}

export async function waitForElement(
  selector: string,
  {
    timeout = 4000,
    interval = 100,
  }: {
    timeout?: number;
    interval?: number;
  } = {},
): Promise<HTMLElement | null> {
  if (typeof window === "undefined") return null;

  const startedAt = Date.now();

  return new Promise((resolve) => {
    const check = () => {
      const element = document.querySelector<HTMLElement>(selector);
      if (element) {
        resolve(element);
        return;
      }

      if (Date.now() - startedAt >= timeout) {
        resolve(null);
        return;
      }

      window.setTimeout(check, interval);
    };

    check();
  });
}
